//! Byte-exact golden corpus tests (M1 T1.5).
//!
//! `fixtures/transit-corpus.json` is generated by transit-js — the same library
//! the Penpot frontend bundles — so it is the oracle for wire form. Each case is
//! decoded by the Rust reader and re-encoded by the Rust writer; for the cases
//! marked `roundtrip` the bytes must be identical.
//!
//! All failures are collected and reported in one pass, because a single cache
//! off-by-one usually breaks dozens of cases and the whole list is more useful
//! than the first assertion.

use std::fmt::Write as _;
use std::path::PathBuf;

use serde::Deserialize;
use transit::{decode, encode, PathData, Value};

#[derive(Debug, Deserialize)]
struct Corpus {
    #[serde(rename = "generatedBy")]
    #[allow(dead_code)]
    generated_by: String,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    #[allow(dead_code)]
    note: String,
    wire: String,
    #[serde(rename = "expect_wire")]
    expect_wire: String,
    canonical: bool,
    #[serde(rename = "expectSource", default)]
    #[allow(dead_code)]
    expect_source: String,
    #[serde(default)]
    expect: Option<Expect>,
}

#[derive(Debug, Deserialize, Default)]
struct Expect {
    #[serde(default)]
    svg: Option<String>,
}

fn corpus() -> Corpus {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("fixtures")
        .join("transit-corpus.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("bad corpus JSON: {e}"))
}

#[test]
fn corpus_is_substantial() {
    let corpus = corpus();
    assert!(
        corpus.cases.len() >= 60,
        "PLAN.md T1.5 asks for at least 60 samples, got {}",
        corpus.cases.len()
    );
    let names: Vec<&str> = corpus.cases.iter().map(|c| c.name.as_str()).collect();
    let mut sorted = names.clone();
    sorted.sort_unstable();
    sorted.dedup();
    assert_eq!(
        sorted.len(),
        names.len(),
        "corpus case names must be unique"
    );
}

#[test]
fn golden_encode_matches_the_oracles_canonical_form() {
    let corpus = corpus();
    let mut decode_failures = Vec::new();
    let mut byte_diffs = Vec::new();
    let mut unstable = Vec::new();
    let mut ok = 0usize;

    for case in &corpus.cases {
        let value = match decode(&case.wire) {
            Ok(value) => value,
            Err(e) => {
                decode_failures.push(format!("{}: {e}  [wire: {}]", case.name, case.wire));
                continue;
            }
        };

        let reencoded = encode(&value);
        if reencoded == case.expect_wire {
            ok += 1;
        } else {
            byte_diffs.push(format!(
                "{}\n    oracle:    {}\n    expected:  {}\n    rust:      {}",
                case.name, case.wire, case.expect_wire, reencoded
            ));
        }

        // The canonical form must be a fixed point of our own codec, otherwise
        // two successive RPC round trips would keep changing the bytes.
        let second = decode(&reencoded).map(|v| encode(&v));
        let stable = matches!(&second, Ok(text) if *text == reencoded);
        if !stable {
            unstable.push(format!(
                "{}: encode(decode(x)) is not a fixed point\n    first:  {}\n    second: {:?}",
                case.name, reencoded, second
            ));
        }
    }

    if !(decode_failures.is_empty() && byte_diffs.is_empty() && unstable.is_empty()) {
        let mut report = String::new();
        if !decode_failures.is_empty() {
            let _ = write!(
                report,
                "\n--- decode failures ({}) ---\n{}\n",
                decode_failures.len(),
                decode_failures.join("\n")
            );
        }
        if !byte_diffs.is_empty() {
            let _ = write!(
                report,
                "\n--- byte diffs vs canonical form ({}) ---\n{}\n",
                byte_diffs.len(),
                byte_diffs.join("\n")
            );
        }
        if !unstable.is_empty() {
            let _ = write!(
                report,
                "\n--- not fixed points ({}) ---\n{}\n",
                unstable.len(),
                unstable.join("\n")
            );
        }
        panic!("{report}\n{ok} of {} cases matched", corpus.cases.len());
    }
}

/// Every corpus case that the oracle already emits canonically must come out of
/// our writer unchanged. This is the strict byte-exactness claim: it covers the
/// referent cache, the vector/array asymmetry and the top-level quoting rules.
#[test]
fn canonical_inputs_are_reproduced_byte_for_byte() {
    let corpus = corpus();
    let canonical: Vec<&Case> = corpus.cases.iter().filter(|c| c.canonical).collect();
    assert!(
        canonical.len() >= 80,
        "most corpus inputs should already be canonical, got {}/{}",
        canonical.len(),
        corpus.cases.len()
    );
    let mut diffs = Vec::new();
    for case in &canonical {
        let value =
            decode(&case.wire).unwrap_or_else(|e| panic!("{}: decode failed: {e}", case.name));
        let text = encode(&value);
        if text != case.wire {
            diffs.push(format!(
                "{}\n    oracle: {}\n    rust:   {}",
                case.name, case.wire, text
            ));
        }
    }
    assert!(
        diffs.is_empty(),
        "byte diffs in {} canonical cases:\n{}",
        diffs.len(),
        diffs.join("\n")
    );
}

#[test]
fn path_data_expectations_hold() {
    let corpus = corpus();
    for case in &corpus.cases {
        let Some(Expect { svg: Some(svg) }) = case.expect.as_ref() else {
            continue;
        };
        let value = decode(&case.wire).unwrap_or_else(|e| panic!("{}: {e}", case.name));
        let Value::PathData(path) = value else {
            panic!("{}: expected PathData, got {value:?}", case.name);
        };
        assert_eq!(&path.to_svg(), svg, "{}: svg form", case.name);
    }
}

/// The two Penpot-specific invariants that plain byte equality cannot express.
#[allow(clippy::float_cmp, reason = "the clamp writes those bounds verbatim")]
#[test]
fn corpus_specific_semantics() {
    let corpus = corpus();
    let find = |name: &str| {
        corpus
            .cases
            .iter()
            .find(|c| c.name == name)
            .unwrap_or_else(|| panic!("corpus has no case `{name}`"))
    };

    // 1. vector vs array stays distinct through the round trip.
    let list = decode(&find("list").wire).expect("list");
    let array = decode(&find("array").wire).expect("array");
    assert!(list.is_vector(), "`~#list` must decode to a vector");
    assert!(
        matches!(array, Value::Array(_)),
        "a bare JSON array must stay an array"
    );
    assert_ne!(
        list, array,
        "vector and array are different values even with the same items"
    );

    // 2. keyword vs string stays distinct.
    let keyword = decode(&find("keyword-simple").wire).expect("keyword");
    let string = decode(&find("string-short").wire).expect("string");
    assert!(matches!(keyword, Value::Keyword(_)));
    assert!(matches!(string, Value::Str(_)));

    // 3. the objects-map case must resolve the repeated outer key through the
    //    cache, which only works if the nested decode used its own reader.
    let objects = decode(&find("objects-map").wire).expect("objects-map");
    let outer = objects
        .get_kw("objects")
        .and_then(Value::as_map)
        .expect("objects is a map");
    assert_eq!(outer.len(), 1, "one shape decoded");
    let shape = outer
        .iter()
        .next()
        .map(|(_, v)| v)
        .expect("the nested shape");
    assert_eq!(shape.tag(), Some("shape"), "nested transit string decoded");
    assert_eq!(shape.get_kw("name"), Some(&Value::str("Board")));
    let again = objects
        .get_kw("again")
        .and_then(|v| v.get_kw("s1"))
        .expect("the cache reference resolves back to ~:s1");
    assert_eq!(again, &Value::str("plain"));

    // 4. clamped coordinates (`normalize-coord` bounds). The comparison is exact
    //    on purpose: the clamp writes those constants verbatim.
    let clamped = decode(&find("path-data-clamped").wire).expect("clamped");
    let Value::PathData(path) = clamped else {
        panic!("expected PathData");
    };
    let seg = path.segment(0).expect("one segment");
    assert_eq!(seg.x, PathData::MAX_SAFE_COORD);
    assert_eq!(seg.y, PathData::MIN_SAFE_COORD);
}
